/// Returns true if sequence `s` starts with prefix `p`.
fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // If prefix is empty, match all
    if p.is_empty() {
        return true;
    }
    // Check length first to avoid out-of-bound access
    if v.len() < p.len() {
        return false;
    }
    // Compare slices element-wise
    v[..p.len()] == p[..]
}

/// Filters input vector `xs` to only those sequences starting with prefix `p`.
fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
        .filter(|seq| has_prefix(seq, &p))
        .collect()
}